"""osc_protocol.py

Tiny binary protocol for shipping a small, fixed set of OSC-style signals over
serial (USB) and then over RF.

Goals:
  - No UDP on the robot: robot talks to an Arduino over USB serial.
  - Arduino stays dumb: it just forwards opaque frames over RF.
  - Fixed table of valid OSC addresses to shrink packets.
  - Binary encoding of args (little-endian) instead of full OSC packets.
  - Optional de-dupe: don't resend unchanged values except at a repeat interval.

This module is shared by:
  - broadcast_state.py (robot)
  - steamdeck_osc_bridge.py (SteamDeck)

Serial framing (USB):
  [0x7E][LEN][PAYLOAD...][CK]
    - LEN is 0..255
    - CK is (LEN + sum(PAYLOAD)) & 0xFF

Payload framing (inside LEN bytes):
  [VER][COUNT][RECORD0...]
  RECORD := [MSG_ID][ARGS...]
    - MSG_ID selects a fixed address + fixed struct format.

NOTE: This is intentionally minimal. If you want stronger corruption
      detection, replace CK with CRC-8/CRC-16.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional, Sequence, Tuple, Union

import os
import errno
import fcntl
import termios
import select
import struct
import time


# -----------------------
# Address table / schema
# -----------------------

PROTOCOL_VERSION: int = 1


@dataclass(frozen=True)
class MsgSpec:
    msg_id: int
    address: str
    fmt: str  # struct format for args (must include endianness, e.g. '<f')

    @property
    def size(self) -> int:
        return struct.calcsize(self.fmt)


