ID_TO_SPEC: Dict[int, MsgSpec] = {m.msg_id: m for m in MSG_TABLE}
ADDR_TO_ID: Dict[str, int] = {m.address: m.msg_id for m in MSG_TABLE}


def pack_args(msg_id: int, args: Sequence[Union[float, int, bool]]) -> bytes:
    spec = ID_TO_SPEC.get(int(msg_id))
    if spec is None:
        raise KeyError(f"Unknown msg_id {msg_id}")
    return struct.pack(spec.fmt, *args)


def unpack_args(msg_id: int, data: bytes, offset: int = 0) -> Tuple[Tuple, int]:
    spec = ID_TO_SPEC.get(int(msg_id))
    if spec is None:
        raise KeyError(f"Unknown msg_id {msg_id}")
    n = spec.size
    if offset + n > len(data):
        raise ValueError("Not enough bytes for args")
    vals = struct.unpack_from(spec.fmt, data, offset)
    return vals, offset + n


def build_payload(records: Sequence[Tuple[int, Sequence]]) -> bytes:
    """Build a protocol payload from (msg_id, args) records."""
    if len(records) > 255:
        raise ValueError("Too many records")
    out = bytearray()
    out.append(PROTOCOL_VERSION & 0xFF)
    out.append(len(records) & 0xFF)
    for msg_id, args in records:
        mid = int(msg_id) & 0xFF
        if mid not in ID_TO_SPEC:
            raise KeyError(f"msg_id {mid} not in table")
        out.append(mid)
        out.extend(pack_args(mid, args))
    return bytes(out)


def parse_payload(payload: bytes) -> List[Tuple[int, Tuple]]:
    """Parse a protocol payload into [(msg_id, args_tuple), ...]."""
    if not payload or len(payload) < 2:
        return []
    ver = payload[0]
    if ver != (PROTOCOL_VERSION & 0xFF):
        return []
    count = payload[1]
    p = 2
    out: List[Tuple[int, Tuple]] = []
    for _ in range(count):
        if p >= len(payload):
            return []
        mid = payload[p]
        p += 1
        try:
            args, p = unpack_args(mid, payload, p)
        except Exception:
            return []
        out.append((mid, args))
    return out


# -----------------------
# Serial framing helpers
# -----------------------

SERIAL_START: int = 0x7E
SERIAL_MAX_LEN: int = 255


def serial_checksum(payload: bytes) -> int:
    return (len(payload) + (sum(payload) & 0xFFFF)) & 0xFF


def serial_frame(payload: bytes) -> bytes:
    if len(payload) > SERIAL_MAX_LEN:
        raise ValueError(f"payload too large: {len(payload)}")
    ck = serial_checksum(payload)
    return bytes([SERIAL_START, len(payload) & 0xFF]) + payload + bytes([ck])


class SerialFrameDecoder:
    """Incremental decoder for the 0x7E/LEN/PAYLOAD/CK serial frames."""

    def __init__(self):
        self._buf = bytearray()

    def feed(self, data: bytes) -> List[bytes]:
        self._buf.extend(data)
        out: List[bytes] = []

        # Simple state machine by scanning.
        while True:
            if len(self._buf) < 3:
                break

            # Find start byte
            try:
                i = self._buf.index(SERIAL_START)
            except ValueError:
                self._buf.clear()
                break

            if i > 0:
                del self._buf[:i]
                if len(self._buf) < 3:
                    break

            ln = self._buf[1]
            if ln > SERIAL_MAX_LEN:
                # impossible; drop start and resync
                del self._buf[0:1]
                continue

            frame_len = 2 + ln + 1
            if len(self._buf) < frame_len:
                break

            payload = bytes(self._buf[2:2 + ln])
            ck = self._buf[2 + ln]
            if ck != serial_checksum(payload):
                # bad frame; drop start and resync
                del self._buf[0:1]
                continue

            out.append(payload)
            del self._buf[:frame_len]

        return out


# -----------------------
# Minimal Linux serial port
# -----------------------

_BAUD_MAP = {
    9600: termios.B9600,
    19200: termios.B19200,
    38400: termios.B38400,
    57600: termios.B57600,
    115200: termios.B115200,
    230400: termios.B230400,
    460800: termios.B460800,
    921600: termios.B921600,
}

# USB CDC devices such as /dev/puddleduck ignore the host baud,
# but allow high-speed constants when the platform exposes them.
for _baud in (1000000, 2000000, 3000000, 4000000):
    _const = getattr(termios, f"B{_baud}", None)
    if _const is not None:
        _BAUD_MAP[_baud] = _const


def open_serial_fd(path: str, baud: int = 115200) -> int:
    """Open and configure a serial port (Linux) without pyserial."""
    if baud not in _BAUD_MAP:
        raise ValueError(f"Unsupported baud {baud} (add to _BAUD_MAP)")

    fd = os.open(path, os.O_RDWR | os.O_NOCTTY | os.O_NONBLOCK)

    attrs = termios.tcgetattr(fd)

    # iflag
    attrs[0] &= ~(termios.IGNBRK | termios.BRKINT | termios.PARMRK | termios.ISTRIP |
                 termios.INLCR | termios.IGNCR | termios.ICRNL | termios.IXON | termios.IXOFF | termios.IXANY)
    # oflag
    attrs[1] &= ~termios.OPOST
    # cflag
    attrs[2] &= ~(termios.CSIZE | termios.PARENB)
    attrs[2] |= (termios.CS8 | termios.CREAD | termios.CLOCAL)
    # lflag
    attrs[3] &= ~(termios.ECHO | termios.ECHONL | termios.ICANON | termios.ISIG | termios.IEXTEN)

    # baud
    speed = _BAUD_MAP[baud]

    # Portable: tcgetattr returns [iflag, oflag, cflag, lflag, ispeed, ospeed, cc]
    # Set indices 4 and 5 directly.
    try:
        attrs[4] = speed  # ispeed
        attrs[5] = speed  # ospeed
    except Exception:
        # Very old/odd platforms: fall back to cfset* if present
        if hasattr(termios, "cfsetispeed"):
            termios.cfsetispeed(attrs, speed)
        if hasattr(termios, "cfsetospeed"):
            termios.cfsetospeed(attrs, speed)

    # VMIN/VTIME (non-blocking reads)
    attrs[6][termios.VMIN] = 0
    attrs[6][termios.VTIME] = 0

    termios.tcsetattr(fd, termios.TCSANOW, attrs)

    # ensure non-blocking
    fl = fcntl.fcntl(fd, fcntl.F_GETFL)
    fcntl.fcntl(fd, fcntl.F_SETFL, fl | os.O_NONBLOCK)
    return fd


class FramedSerial:
    """Convenience wrapper around a Linux serial fd with our framing.
    Resilient to unplug/replug: will reopen the device path automatically.
    """

    def __init__(self, path: str, baud: int = 115200, *, write_lock=None,
                 reconnect_initial_delay_s: float = 0.25,
                 reconnect_max_delay_s: float = 2.0):
        self.path = path
        self.baud = int(baud)
        self.decoder = SerialFrameDecoder()
        self._write_lock = write_lock

        self.fd = -1  # -1 means disconnected
        self._reconnect_delay_s = float(reconnect_initial_delay_s)
        self._reconnect_max_delay_s = float(reconnect_max_delay_s)
        self._next_reconnect_t = 0.0

        self._open_now(best_effort=True)

    def _open_now(self, *, best_effort: bool) -> bool:
        """Try to open immediately; return True if connected."""
        try:
            self.fd = open_serial_fd(self.path, baud=self.baud)
            self.decoder = SerialFrameDecoder()  # reset framing on reconnect
            self._reconnect_delay_s = 0.25
            self._next_reconnect_t = 0.0
            return True
        except Exception:
            self.fd = -1
            if not best_effort:
                raise
            return False

    def _mark_disconnected(self) -> None:
        if self.fd >= 0:
            try:
                os.close(self.fd)
            except Exception:
                pass
        self.fd = -1
        # schedule next reconnect attempt with backoff
        now = time.time()
        if self._next_reconnect_t <= now:
            self._next_reconnect_t = now + self._reconnect_delay_s
            self._reconnect_delay_s = min(self._reconnect_delay_s * 2.0, self._reconnect_max_delay_s)

    def ensure_open(self) -> bool:
        """Ensure we have an open fd; attempt reconnect if needed."""
        if self.fd >= 0:
            return True
        now = time.time()
        if now < self._next_reconnect_t:
            return False
        return self._open_now(best_effort=True)

    def close(self) -> None:
        self._mark_disconnected()

    def write_payload(self, payload: bytes) -> None:
        if not self.ensure_open():
            return  # silently drop while disconnected (caller will resend due to repeats)
        data = serial_frame(payload)

        try:
            if self._write_lock is None:
                os.write(self.fd, data)
            else:
                with self._write_lock:
                    os.write(self.fd, data)
        except OSError as e:
            # Typical unplug errors: EIO, ENODEV, EBADF
            if e.errno in (errno.EIO, errno.ENODEV, errno.EBADF, errno.EPIPE):
                self._mark_disconnected()
                return
            self._mark_disconnected()
            return

    def read_payloads(self, *, max_bytes: int = 4096) -> List[bytes]:
        if not self.ensure_open():
            return []

        try:
            chunk = os.read(self.fd, max_bytes)
        except BlockingIOError:
            return []
        except OSError as e:
            # Typical unplug errors: EIO, ENODEV, EBADF
            if e.errno in (errno.EIO, errno.ENODEV, errno.EBADF):
                self._mark_disconnected()
                return []
            self._mark_disconnected()
            return []

        if not chunk:
            # If the device vanished, Linux often yields errors not EOF, but treat EOF as disconnected too.
            self._mark_disconnected()
            return []

        return self.decoder.feed(chunk)

    def wait_readable(self, timeout_s: float) -> bool:
        # If disconnected, don't block in select(); just try to reconnect opportunistically.
        if not self.ensure_open():
            time.sleep(min(float(timeout_s), 0.05))
            return False
        try:
            r, _, _ = select.select([self.fd], [], [], timeout_s)
            return bool(r)
        except Exception:
            self._mark_disconnected()
            return False


# -----------------------
# De-dupe / rate limiting
# -----------------------


class RateLimitedDeduper:
    """Per-message de-dupe with a repeat interval.

    Semantics:
      - If a value changes, allow it immediately.
      - If it does *not* change, allow it only if at least repeat_interval_s
        has elapsed since the last time it was allowed.
    """

    def __init__(self, repeat_interval_s: float = 2.0):
        self.repeat_interval_s = float(repeat_interval_s)
        # msg_id -> (packed_args_bytes, last_send_time)
        self._last: Dict[int, Tuple[bytes, float]] = {}

    def should_send(self, msg_id: int, packed_args: bytes, *, now: Optional[float] = None) -> bool:
        now = time.time() if now is None else float(now)
        mid = int(msg_id) & 0xFF
        prev = self._last.get(mid)
        if prev is None:
            self._last[mid] = (bytes(packed_args), now)
            return True

        prev_bytes, prev_t = prev
        changed = (prev_bytes != packed_args)
        old = (now - prev_t) >= self.repeat_interval_s if self.repeat_interval_s > 0 else True
        if changed or old:
            self._last[mid] = (bytes(packed_args), now)
            return True
        return False

